const rtdal004923Source0001 = `test_that("assert_dots_empty", {
  f <- function(x, ...) {
    assert_dots_empty()
    TRUE
  }
  expect_true(f())
  expect_true(f(x = 1))
  expect_error(f(x = 1, y = 1))
  expect_error(f(y = 1))
})`

const rtdal004923Source0002 = `test_that("assert_required (simple examples)", {
  # define functions
  f1 <- function(y, w = 1) {assert_required(y); assert_required(w); w + y + 1}
  f2 <- function(x) {assert_required(x); x + 3}
  # tests
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f1(1 + "a")
  )
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f1(object_not_exist)
  )
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(1 + "a")
  )
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(object_not_exist)
  )
})`

const rtdal004923Source0003 = `test_that("assert_required (magrittr pipe)", {
  # define functions
  f1 <- function(y, w = 1) {assert_required(y); assert_required(w); w + y + 1}
  f2 <- function(x) {assert_required(x); x + 3}
  # tests
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(1 + "a") %>%
      f1() %>%
      print()
  )
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(object_not_exist) %>%
      f1() %>%
      print()
  )
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(2) %>%
      f1(1 + "a") %>%
      print()
  )
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(2) %>%
      f1(object_not_exist) %>%
      print()
  )
})`

const rtdal004923Source0004 = `test_that("assert_required (native pipe)", {
  skip_if(getRversion() < "4.1.0", "R version does not support native pipes")
  # define functions
  f1 <- function(y, w = 1) {assert_required(y); assert_required(w); w + y + 1}
  f2 <- function(x) {assert_required(x); x + 3}
  # tests
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(1 + "a") |>
      f1() |>
      print()
  )
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(object_not_exist) |>
      f1() |>
      print()
  )
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(2) |>
      f1(1 + "a") |>
      print()
  )
  expect_snapshot(
    error = TRUE,
    transform = cli::ansi_strip,
    f2(2) |>
      f1(object_not_exist) |>
      print()
  )
})`

const rtdal004923Source0005 = "test_that(\"assert_required (prioritizr examples, magrittr pipe)\", {\n  # load data\n  sim_pu_raster <- get_sim_pu_raster()\n  sim_features <- get_sim_features()\n  # tests\n  ## check that \"caused by error\" appears in msg when object not found\n  expect_snapshot(\n    error = TRUE,\n    transform = cli::ansi_strip,\n    problem(sim_pu_raster, sim_features) %>%\n      add_relative_targets(object_not_exist) %>%\n      add_min_set_objective() %>%\n      add_binary_decisions() %>%\n      print()\n  )\n  expect_snapshot(\n    error = TRUE,\n    transform = cli::ansi_strip,\n    problem(sim_pu_raster, sim_features) %>%\n      add_min_shortfall_objective(budget = object_not_exist) %>%\n      add_relative_targets(0.1) %>%\n      add_binary_decisions() %>%\n      print()\n  )\n  ## check that \"caused by `expression`\" appears in msg when object not found\n  expect_snapshot(\n    error = TRUE,\n    transform = cli::ansi_strip,\n    problem(sim_pu_raster, sim_features) %>%\n      add_relative_targets(1 + \"a\") %>%\n      add_min_set_objective() %>%\n      add_binary_decisions() %>%\n      print()\n  )\n  ## check order of errors is correct\n  expect_snapshot(\n    error = TRUE,\n    transform = cli::ansi_strip,\n    problem(object_not_exist, sim_features) %>%\n      add_relative_targets(1 + \"a\") %>%\n      add_min_set_objective() %>%\n      add_binary_decisions() %>%\n      print()\n  )\n  ## check error occurs regardless of position in pipe-chain\n  expect_snapshot(\n    error = TRUE,\n    transform = cli::ansi_strip,\n    problem(sim_pu_raster, sim_features) %>%\n      add_min_set_objective() %>%\n      add_binary_decisions() %>%\n      add_relative_targets(1 + \"a\") %>%\n      print()\n  )\n  expect_snapshot(\n    error = TRUE,\n    transform = cli::ansi_strip,\n    problem(sim_pu_raster, sim_features) %>%\n      add_min_set_objective() %>%\n      add_binary_decisions() %>%\n      add_relative_targets(object_not_exist) %>%\n      print()\n  )\n})"

