const rtdal004957Source0001 = `test_that("x = sf", {
  crs <- sf::st_crs(3875)
  g <- sf::st_sfc(list(sf::st_point(c(1, 0)), sf::st_point(c(0, 1))), crs = crs)
  x <- sf::st_as_sf(tibble::tibble(x = c(0, NA), y = c(0, NA), geom = g))
  expect_equal(get_crs(x)[[2]], crs[[2]])
})`

const rtdal004957Source0002 = `test_that("x = SpatRaster", {
  crs <- sf::st_crs(3875)
  x <- terra::rast(matrix(c(0, 1, 2, NA)), crs = crs[[2]])
  expect_equal(get_crs(x)[[2]], crs[[2]])
})`

const rtdal004957Source0003 = `test_that("x = ZonesSpatRaster", {
  crs <- sf::st_crs(3875)
  x <- zones(
    terra::rast(matrix(c(0, 1, 2, NA)), crs = crs[[2]]),
    terra::rast(matrix(c(0, 5, 2, NA)), crs = crs[[2]])
  )
  expect_equal(get_crs(x)[[2]], crs[[2]])
})`

const rtdal004957Source0004 = `test_that("x = Raster", {
  crs <- sf::st_crs(3875)
  x <- raster::raster(terra::rast(matrix(c(0, 1, 2, NA)), crs = crs[[2]]))
  expect_true(is.character(get_crs(x)[[2]]))
})`

const rtdal004957Source0005 = `test_that("x = Spatial", {
  crs <- sf::st_crs(3875)
  g <- sf::st_sfc(list(sf::st_point(c(1, 0)), sf::st_point(c(0, 1))), crs = crs)
  x <- sf::st_as_sf(tibble::tibble(x = c(0, NA), y = c(0, NA), geom = g))
  x <- sf::as_Spatial(x)
  expect_equal(get_crs(x)[[2]], crs[[2]])
})`

const rtdal004957Source0006 = `test_that("x = ZonesRaster", {
  crs <- sf::st_crs(3875)
  expect_warning(
    x <- zones(
      raster::raster(matrix(c(0, 1, 2, NA)), crs = crs[[2]]),
      raster::raster(matrix(c(0, 1, -2, NA)), crs = crs[[2]])
    ),
    "deprecated"
  )
  expect_true(is.character(get_crs(x)[[2]]))
})`

