const rtdal004969Source0007 = `test_that("append methods", {
  # data
  l <- list(
    modelsense = "min",
    A_i = c(0L, 1L, 1L),
    A_j = c(0L, 1L, 2L),
    A_x = c(7, 8, 9),
    obj = c(9, 10, 11),
    lb = c(12, 13, 14),
    ub = c(15, 16, 17),
    rhs = c(18, 19),
    number_of_features = 2,
    number_of_planning_units = 3,
    number_of_zones = 1,
    sense = c("=", "="),
    vtype = c("B", "S", "C"),
    row_ids = c("a", "b"),
    col_ids = c("d", "e", "f"),
    compressed_formulation = FALSE)
  x <- optimization_problem(l)
  # single new constraint
  c1_A <- Matrix::sparseMatrix(
    i = c(1, 1), j = c(1, 3), x = c(90, -12), dims = c(1, 3), repr = "T"
  )
  c1_rhs <- 123
  c1_sense <- "="
  c1_row_ids <- "c1"
  append_linear_constraints(x, c1_rhs, c1_sense, c1_A, c1_row_ids)
  # multiple new constraints
  c2_A <- Matrix::sparseMatrix(
    i = c(1, 1, 2), j = c(3, 2, 1), x = c(12, 8, 45), dims = c(2, 3), repr = "T"
  )
  c2_rhs <- c(34, 12)
  c2_sense <- c("<=", ">=")
  c2_row_ids <- c("c2", "c3")
  append_linear_constraints(x, c2_rhs, c2_sense, c2_A, c2_row_ids)
  # tests
  expect_equal(
    x$rhs(),
    c(18, 19, c1_rhs, c2_rhs)
  )
  expect_equal(
    x$sense(),
    c("=", "=", c1_sense, c2_sense)
  )
  expect_equal(
    x$row_ids(),
    c("a", "b", c1_row_ids, c2_row_ids)
  )
  expect_equal(
    x$A(),
    rbind(
      Matrix::sparseMatrix(
        i = 1 + c(0L, 1L, 1L),
        j = 1 + c(0L, 1L, 2L),
        x = c(7, 8, 9),
        dims = c(2, 3)
      ),
      c1_A,
      c2_A
    )
  )
})`

