const rtdal004970Source0001 = `test_that("x = sf (single cost column)", {
  # create data
  d <- get_sim_pu_polygons()
  # correct results
  x <- planning_unit_indices(d, "cost")
  y <- which(!is.na(d$cost))
  # tests
  expect_equal(x, y)
})`

const rtdal004970Source0002 = `test_that("x = sf (single multiple column)", {
  # create data
  d <- get_sim_pu_polygons()
  d$cost2 <- 1
  d$cost2[1:6] <- NA_real_
  # correct results
  x <- planning_unit_indices(d, c("cost", "cost2"))
  y <- which(!is.na(d$cost) | !is.na(d$cost2))
  # tests
  expect_equal(x, y)
})`

const rtdal004970Source0003 = `test_that("x = SpatRaster (single layer)", {
  # create data
  d <- get_sim_pu_raster()
  # correct results
  x <- planning_unit_indices(d)
  y <- terra::cells(terra::allNA(d), 0)[[1]]
  # tests
  expect_equal(x, y)
})`

const rtdal004970Source0004 = `test_that("x = SpatRaster (multiple layers)", {
  # create data
  d <- get_sim_zones_pu_raster()
  # correct results
  x <- planning_unit_indices(d)
  y <- terra::cells(terra::allNA(d), 0)[[1]]
  # tests
  expect_equal(x, y)
})`

const rtdal004970Source0005 = `test_that("x = data.frame", {
  # create data
  d <- matrix(runif(30), ncol = 3, nrow = 10)
  d[1, ] <- NA
  d[4, ] <- NA
  d[c(6, 8, 12, 23, 27)] <- NA
  d <- as.data.frame(d)
  # correct results
  x <- planning_unit_indices(d, names(d))
  y <- which(rowSums(is.na(d)) != ncol(d))
  # tests
  expect_equal(x, y)
})`

