const rtdal004977Source0009 = "test_that(\"x = data.frame, features = data.frame (single zone)\", {\n  # create data\n  pu <- data.frame(id = seq_len(10), cost = c(0.1, NA, runif(8, -1, 1)))\n  species <- data.frame(id = seq_len(5), name = letters[1:5], targets = 0.5)\n  rij <- expand.grid(pu = seq_len(9), species = seq_len(5))\n  rij$amount <- runif(nrow(rij), -1, 1)\n  # create problem\n  w <- capture_warnings(\n    x <- problem(pu, species, rij, \"cost\"),\n    ignore_deprecation = TRUE\n  )\n  # check warnings\n  expect_length(w, 2)\n  expect_match(w[[1]], \"x\")\n  expect_match(w[[1]], \"negative\")\n  expect_match(w[[2]], \"rij\")\n  expect_match(w[[2]], \"negative\")\n  # verify that object can be printed\n  suppressMessages(print(x))\n  suppressMessages(x)\n  # tests for integer fields\n  expect_equal(x$feature_names(), letters[1:5])\n  expect_equal(x$zone_names(), \"cost\")\n  expect_equal(x$number_of_features(), 5)\n  expect_equal(x$number_of_zones(), 1)\n  expect_equal(x$number_of_planning_units(), 9)\n  expect_equal(x$planning_unit_indices(), which(!is.na(pu$cost)))\n  expect_equal(x$number_of_total_units(), 10)\n  # tests for planning_unit_costs field\n  expect_equal(\n    x$planning_unit_costs(),\n    matrix(pu$cost[-2], ncol = 1),\n    ignore_attr = TRUE\n  )\n  expect_equal(colnames(x$planning_unit_costs()), \"cost\")\n  # tests for feature_abundances_in_planning_units field\n  rij2 <- rij[rij$pu != 2, ]\n  expect_equal(\n    x$feature_abundances_in_planning_units(),\n    Matrix::rowSums(\n      Matrix::sparseMatrix(i = rij2[[2]], j = rij2[[1]], x = rij2[[3]])\n    ),\n    ignore_attr = TRUE\n  )\n  expect_equal(rownames(x$feature_abundances_in_planning_units()), letters[1:5])\n  expect_equal(colnames(x$feature_abundances_in_planning_units()), \"cost\")\n  # tests for feature_abundances_in_total_units field\n  expect_equal(\n    x$feature_abundances_in_total_units(),\n    Matrix::rowSums(\n      Matrix::sparseMatrix(i = rij[[2]], j = rij[[1]], x = rij[[3]])\n    ),\n    ignore_attr = TRUE\n  )\n  expect_equal(rownames(x$feature_abundances_in_total_units()), letters[1:5])\n  expect_equal(colnames(x$feature_abundances_in_total_units()), \"cost\")\n  # tests for rij_matrix field\n  rij2 <- rij[rij$pu != 2, ]\n  rij2$pu <- match(rij2$pu, pu$id[-2])\n  expect_equal(\n    x$data$rij_matrix[[1]],\n    `rownames<-`(\n      Matrix::sparseMatrix(\n        i = rij2[[2]], j = rij2[[1]], x = rij2[[3]], dims = c(5, 9)\n      ),\n      x$feature_names()\n    ),\n    ignore_attr = TRUE\n  )\n  expect_equal(names(x$data$rij_matrix), \"cost\")\n  expect_equal(rownames(x$data$rij_matrix[[1]]), letters[1:5])\n  expect_true(x$has_negative_feature_data())\n  # test that calling targets before they have been initialized throws error\n  expect_error(x$feature_targets())\n})"

const rtdal004977Source0010 = `test_that("x = data.frame, features = data.frame (multiple zones)", {
  # import data
  pu <- data.frame(
    id = seq_len(10),
    cost_1 = c(0.1, NA, runif(8, -1, 1)),
    cost_2 = c(NA, NA, runif(8, -1, 1))
  )
  species <- data.frame(id = seq_len(5), name = letters[1:5], targets = 0.5)
  rij <- expand.grid(pu = seq_len(9), species = seq_len(5), zone = 1:2)
  rij$amount <- runif(nrow(rij), -1, 1)
  z <- data.frame(id = 1:2, name = c("z1", "z2"))
  # create problem
  w <- capture_warnings(
    x <- problem(pu, species, rij, c("cost_1", "cost_2"), z),
    ignore_deprecation = TRUE
  )
  # check warnings
  expect_length(w, 2)
  expect_match(w[[1]], "x")
  expect_match(w[[1]], "negative")
  expect_match(w[[2]], "rij")
  expect_match(w[[2]], "negative")
  # verify that object can be printed
  suppressMessages(print(x))
  suppressMessages(x)
  # tests for integer fields
  expect_equal(x$feature_names(), letters[1:5])
  expect_equal(x$zone_names(), c("z1", "z2"))
  expect_equal(x$number_of_features(), 5)
  expect_equal(x$number_of_zones(), 2)
  expect_equal(x$number_of_planning_units(), 9)
  expect_equal(x$planning_unit_indices(), c(1, seq(3, nrow(pu))))
  expect_equal(x$number_of_total_units(), 10)
  # tests for planning_unit_costs field
  expect_equal(
    x$planning_unit_costs(),
    as.matrix(pu[-2, 2:3]),
    ignore_attr = TRUE
  )
  expect_equal(colnames(x$planning_unit_costs()), c("z1", "z2"))
  # tests for feature_abundances_in_planning_units field
  rij2 <- rij
  rij2 <- rij2[!(rij2$pu %in% pu$id[is.na(pu$cost_1)] & rij2$zone == 1), ]
  rij2 <- rij2[!(rij2$pu %in% pu$id[is.na(pu$cost_2)] & rij2$zone == 2), ]
  expect_equal(
    x$feature_abundances_in_planning_units(),
    matrix(
      aggregate(rij2[[4]], by = list(rij2[[2]], rij2[[3]]), sum)[[3]],
      ncol = 2,
      dimnames = list(x$feature_names(), x$zone_names())
    )
  )
  expect_equal(rownames(x$feature_abundances_in_planning_units()), letters[1:5])
  expect_equal(
    colnames(x$feature_abundances_in_planning_units()),
    c("z1", "z2")
  )
  # tests for feature_abundances_in_total_units field
  expect_equal(
    x$feature_abundances_in_total_units(),
    matrix(
      aggregate(rij[[4]], by = list(rij[[2]], rij[[3]]), sum)[[3]],
      ncol = 2
    ),
    ignore_attr = TRUE
  )
  expect_equal(rownames(x$feature_abundances_in_total_units()), letters[1:5])
  expect_equal(
    colnames(x$feature_abundances_in_total_units()),
    c("z1", "z2")
  )
  # tests for rij_matrix field
  rij2 <- rij[rij$pu != 2, ]
  rij2$pu <- match(rij2$pu, unique(sort(rij2$pu)))
  expect_equal(names(x$data$rij_matrix), c("z1", "z2"))
  expect_equal(
    x$data$rij_matrix[[1]],
    Matrix::sparseMatrix(
      i = rij2[[2]][rij2[[3]] == 1],
      j = rij2[[1]][rij2[[3]] == 1],
      x = rij2[[4]][rij2[[3]] == 1],
      dims = c(5, 9),
      dimnames = list(x$feature_names(), NULL)
    ),
    ignore_attr = TRUE
  )
  expect_equal(
    x$data$rij_matrix[[2]],
    Matrix::sparseMatrix(
      i = rij2[[2]][rij2[[3]] == 2],
      j = rij2[[1]][rij2[[3]] == 2],
      x = rij2[[4]][rij2[[3]] == 2],
      dims = c(5, 9),
      dimnames = list(x$feature_names(), NULL)
    ),
    ignore_attr = TRUE
  )
  expect_equal(rownames(x$data$rij_matrix[[1]]), letters[1:5])
  expect_equal(rownames(x$data$rij_matrix[[2]]), letters[1:5])
  expect_true(x$has_negative_feature_data())
  # test that calling targets before they have been initialized throws error
  expect_error(x$feature_targets())
})`

const rtdal004977Source0011 = `test_that("x = numeric, features = data.frame", {
  # import data
  pu <- data.frame(
    id = seq_len(10),
    cost = c(0.2, NA, runif(8, -1, 1)),
    spp1 = runif(10, -1, 1), spp2 = c(rpois(9, 4), NA)
  )
  # create problem
  w <- capture_warnings(
    x <- problem(
      pu$cost,
      data.frame(id = seq_len(2), name = c("spp1", "spp2")),
      as.matrix(t(pu[, 3:4]))
    )
  )
  # check warnings
  expect_length(w, 2)
  expect_match(w[[1]], "x")
  expect_match(w[[1]], "negative")
  expect_match(w[[2]], "rij_matrix")
  expect_match(w[[2]], "negative")
  # verify that object can be printed
  suppressMessages(print(x))
  suppressMessages(x)
  # tests for integer fields
  expect_equal(x$feature_names(), c("spp1", "spp2"))
  expect_equal(x$zone_names(), "1")
  expect_equal(x$number_of_features(), 2)
  expect_equal(x$number_of_zones(), 1)
  expect_equal(x$number_of_planning_units(), 9)
  expect_equal(x$planning_unit_indices(), which(!is.na(pu$cost)))
  expect_equal(x$number_of_total_units(), 10)
  # tests for planning_unit_costs field
  expect_equal(
    x$planning_unit_costs(),
    matrix(pu$cost[-2], ncol = 1),
    ignore_attr = TRUE
  )
  expect_equal(colnames(x$planning_unit_costs()), "1")
  # tests for feature_abundances_in_planning_units field
  expect_equal(
    x$feature_abundances_in_planning_units(),
    rowSums(t(pu[-2, 3:4]), na.rm = TRUE),
    ignore_attr = TRUE
  )
  expect_equal(
    rownames(x$feature_abundances_in_planning_units()),
    c("spp1", "spp2")
  )
  expect_equal(colnames(x$feature_abundances_in_planning_units()), "1")
  # tests for feature_abundances_in_total_units field
  expect_equal(
    x$feature_abundances_in_total_units(),
    rowSums(t(pu[, 3:4]), na.rm = TRUE),
    ignore_attr = TRUE
  )
  expect_equal(
    rownames(x$feature_abundances_in_total_units()),
    c("spp1", "spp2")
  )
  expect_equal(colnames(x$feature_abundances_in_total_units()), "1")
  # tests for rij_matrix field
  expect_equal(names(x$data$rij_matrix), "1")
  expect_equal(
    x$data$rij_matrix[[1]],
    {
      m <- as_Matrix(t(pu[-2, 3:4]), "dgCMatrix")
      rownames(m) <- x$feature_names()
      colnames(m) <- NULL
      m@x[is.na(m@x)] <- 0
      Matrix::drop0(m)
    },
    ignore_attr = TRUE
  )
  expect_equal(rownames(x$data$rij_matrix[[1]]), c("spp1", "spp2"))
  expect_true(x$has_negative_feature_data())
  # test that calling targets before they have been initialized throws error
  expect_error(x$feature_targets())
})`

const rtdal004977Source0012 = `test_that("x = matrix, features = data.frame", {
  # import data
  pu <- data.frame(
    id = seq_len(10),
    cost_1 = c(NA, NA, runif(8, -1, 1)), cost_2 = c(0.3, NA, runif(8, -1, 1)),
    spp1_1 = runif(10, -1, 1), spp2_1 = c(rpois(9, 4), NA),
    spp1_2 = runif(10, -1, 1), spp2_2 = runif(10, -1, 1)
  )
  # create problem
  w <- capture_warnings(
    x <- problem(
      as.matrix(pu[, 2:3]),
      data.frame(id = seq_len(2), name = c("spp1", "spp2")),
      list(as.matrix(t(pu[, 4:5])), as.matrix(t(pu[, 6:7])))
    ),
    ignore_deprecation = TRUE
  )
  # check warnings
  expect_length(w, 2)
  expect_match(w[[1]], "x")
  expect_match(w[[1]], "negative")
  expect_match(w[[2]], "rij_matrix")
  expect_match(w[[2]], "negative")
  # verify that object can be printed
  suppressMessages(print(x))
  suppressMessages(x)
  # tests for integer fields
  expect_equal(x$feature_names(), c("spp1", "spp2"))
  expect_equal(x$zone_names(), c("1", "2"))
  expect_equal(x$number_of_features(), 2)
  expect_equal(x$number_of_zones(), 2)
  expect_equal(x$number_of_planning_units(), 9)
  expect_equal(x$planning_unit_indices(), c(1, seq(3, nrow(pu))))
  expect_equal(x$number_of_total_units(), 10)
  # tests for planning_unit_costs field
  expect_equal(
    x$planning_unit_costs(),
    as.matrix(pu[-2, 2:3]),
    ignore_attr = TRUE
  )
  expect_equal(colnames(x$planning_unit_costs()), c("1", "2"))
  # tests for feature_abundances_in_planning_units field
  expect_equal(
    x$feature_abundances_in_planning_units(),
    matrix(
      c(
        sum(pu$spp1_1[!is.na(pu$cost_1)], na.rm = TRUE),
        sum(pu$spp2_1[!is.na(pu$cost_1)], na.rm = TRUE),
        sum(pu$spp1_2[!is.na(pu$cost_2)], na.rm = TRUE),
        sum(pu$spp2_2[!is.na(pu$cost_2)], na.rm = TRUE)
      ),
      ncol = 2,
      dimnames = list(x$feature_names(), x$zone_names())
    )
  )
  expect_equal(
    rownames(x$feature_abundances_in_planning_units()),
    c("spp1", "spp2")
  )
  expect_equal(colnames(x$feature_abundances_in_planning_units()), c("1", "2"))
  # tests for feature_abundances_in_total_units field
  expect_equal(
    x$feature_abundances_in_total_units(),
    matrix(colSums(pu[, 4:7], na.rm = TRUE), ncol = 2),
    ignore_attr = TRUE
  )
  expect_equal(
    rownames(x$feature_abundances_in_total_units()),
    c("spp1", "spp2")
  )
  expect_equal(colnames(x$feature_abundances_in_total_units()), c("1", "2"))
  # tests for rij_matrix field
  expect_equal(names(x$data$rij_matrix), c("1", "2"))
  expect_equal(
    x$data$rij_matrix[[1]],
    {
      m <- as_Matrix(t(pu[-2, 4:5]), "dgCMatrix")
      rownames(m) <- x$feature_names()
      colnames(m) <- NULL
      m@x[is.na(m@x)] <- 0
      Matrix::drop0(m)
    },
    ignore_attr = TRUE
  )
  expect_equal(
    x$data$rij_matrix[[2]],
    {
      m <- as_Matrix(t(pu[-2, 6:7]), "dgCMatrix")
      rownames(m) <- x$feature_names()
      colnames(m) <- NULL
      m@x[is.na(m@x)] <- 0
      Matrix::drop0(m)
    },
    ignore_attr = TRUE
  )
  expect_equal(rownames(x$data$rij_matrix[[1]]), c("spp1", "spp2"))
  expect_equal(rownames(x$data$rij_matrix[[2]]), c("spp1", "spp2"))
  expect_true(x$has_negative_feature_data())
  # test that calling targets before they have been initialized throws error
  expect_error(x$feature_targets())
})`

