const rtdal004978Source0001 = `test_that("SpatRaster (adjacent non-NA pixels are proximal)", {
  # create data
  x <- terra::rast(
    matrix(c(NA, 2:9), ncol = 3),
    extent = terra::ext(0, 3, 0, 3)
  )
  # create matrix
  m <- proximity_matrix(x, distance = 1)
  # calculate correct results
  s <- boundary_matrix(x)
  s[s > 0] <- 1
  Matrix::diag(s) <- 0
  s <- Matrix::drop0(as(s, "symmetricMatrix"))
  # tests
  expect_true(inherits(m, "dsCMatrix"))
  expect_true(all(m == s))
})`

const rtdal004978Source0002 = `test_that("SpatRaster (all non-NA pixels are proximal)", {
  # create data
  x <- terra::rast(
    matrix(c(NA, 2:8, NA), byrow = TRUE, ncol = 3),
    extent = terra::ext(0, 3, 0, 3)
  )
  # create matrix
  m <- proximity_matrix(x, distance = 100)
  # create correct results
  s <- matrix(1, ncol = 9, nrow = 9)
  diag(s) <- 0
  s[, 1] <- 0
  s[, 9] <- 0
  s[1, ] <- 0
  s[9, ] <- 0
  s <- as(as_Matrix(s, "dgCMatrix"), "symmetricMatrix")
  # tests
  expect_true(inherits(m, "dsCMatrix"))
  expect_equal(s, m)
})`

const rtdal004978Source0003 = `test_that("SpatRaster (none are proximal)", {
  # create data
  x <- terra::rast(
    matrix(c(NA, 2:8, NA), byrow = TRUE, ncol = 3),
    extent = terra::ext(0, 3, 0, 3)
  )
  # create matrix
  m <- proximity_matrix(x, distance = 1e-3)
  # create correct results
  s <- Matrix::sparseMatrix(
    i = integer(0), j = integer(0), x = numeric(0), dims = c(9, 9)
  )
  s <- as(s, "symmetricMatrix")
  # tests
  expect_equal(s, m)
})`

const rtdal004978Source0004 = `test_that("SpatRaster (multiple layers)", {
  # create data
  x <- c(
    terra::rast(
      matrix(c(NA, NA, 3:9), ncol = 3),
      extent = terra::ext(0, 3, 0, 3)
    ),
    terra::rast(
      matrix(c(NA, 2:9), ncol = 3),
      extent = terra::ext(0, 3, 0, 3)
    )
  )
  # create matrix
  m <- proximity_matrix(x, distance = 1)
  # calculate correct result
  s <- boundary_matrix(x)
  s[s > 0] <- 1
  Matrix::diag(s) <- 0
  s <- Matrix::drop0(as(s, "symmetricMatrix"))
  # tests
  expect_true(inherits(m, "dsCMatrix"))
  expect_true(all(m == s))
  expect_true(all(m[1, ] == 0))
  expect_true(all(m[, 1] == 0))
  expect_gt(min(Matrix::rowSums(m)[-1]), 0)
})`

