const rtdal004978Source0009 = `test_that("sf (intersecting lines are proximal)", {
  # create data
  x <- sf::st_as_sf(
    tibble::tibble(
      geometry = sf::st_sfc(
        sf::st_linestring(
          matrix(
            c(
              0, 0,
              1, 1,
              2, 2
            ),
            ncol = 2, byrow = TRUE
          )
        ),
        sf::st_linestring(
          matrix(
            c(
              2, 2,
              3, 3,
              4, 4
            ),
            ncol = 2, byrow = TRUE
          )
        ),
        sf::st_linestring(
          matrix(
            c(
              5, 5,
              7, 7
            ),
            ncol = 2, byrow = TRUE
          )
        ),
        sf::st_linestring(
          matrix(
            c(
              0, 1,
              4, 1
            ),
            ncol = 2, byrow = TRUE
          )
        )
      )
    )
  )
  # create matrix
  m <- proximity_matrix(x, distance = 1e-3)
  # create correct matrix
  s <- Matrix::sparseMatrix(
    i = c(1, 1),
    j = c(2, 4),
    x = c(1, 1),
    dims = c(4, 4),
    symmetric = TRUE
  )
  # tests
  expect_true(inherits(m, "dsCMatrix"))
  expect_equal(s, m)
})`

