const rtdal004978Source0018 = `test_that("invalid input", {
  # create data
  data(iris)
  x <- sf::st_sf(
    id = c(1, 2),
    geom = sf::st_sfc(
      sf::st_point(x = c(1, 2)),
      sf::st_geometrycollection(
        list(
          sf::st_point(x = c(10, 20)),
          sf::st_point(x = c(100, 200))
        )
      )
    )
  )
  # tests
  expect_tidy_error(
    proximity_matrix(x, 2),
    "GEOMETRYCOLLECTION"
  )
  expect_tidy_error(
    proximity_matrix(4, 1),
    "must be"
  )
  expect_tidy_error(
    proximity_matrix(iris),
    "must be"
  )
})`

