const rtdal005011Source0027 = `is_env_vector <- function(x) {
  if (is_named_character(x)) {
    return(TRUE)
  }
  if (!is.character(x) || anyNA(x)) {
    return(FALSE)
  }
  if (is.null(names(x))) {
    all(x == "current")
  } else {
    all(x[names(x) == ""] == "current")
  }
}`

