const rtdal005022Source0001 = `process_format <- function(self, private) {
  state <- if (self$is_alive()) {
    pid <- self$get_pid()
    paste0("running, pid ", paste(pid, collapse = ", "), ".")
  } else {
    "finished."
  }

  paste0(
    "PROCESS ",
    "'",
    private$get_short_name(),
    "', ",
    state,
    "\n"
  )
}`

const rtdal005022Source0004 = `pipeline_format <- function(self, private) {
  lines <- vapply(private$procs, function(p) {
    sub("^PROCESS ", "| ", p$format())
  }, character(1L))
  paste0(c("PIPELINE\n", lines), collapse = "")
}`

