const rtdal005026Source0009 = `print.system_command_error <- function(x, ...) {
  writeLines(format(x, ...))
}`

const rtdal005026Source0010 = `system_error_parts <- function(x) {
  c(
    "---",
    paste0("Exit status: ", x$status),
    if (x$echo) {
      "stdout & stderr: <printed>"
    } else {
      std <- if (x$stderr_to_stdout) "Stdout & stderr" else "Stderr"
      last_stderr_lines(x$stderr, std)
    }
  )
}`

const rtdal005026Source0011 = "last_stderr_lines <- function(text, std, prefix = \"\") {\n  if (!nzchar(text)) {\n    return(paste0(std, \": <empty>\"))\n  }\n  lines <- strsplit(text, \"\\r?\\n\")[[1]]\n\n  if (is_interactive() && length(lines) > 10) {\n    std <- paste0(std, \" (last 10 lines, see `$stderr` for more)\")\n    lines <- utils::tail(lines, 10)\n  }\n\n  c(\n    paste0(std, \":\"),\n    paste0(prefix, lines)\n  )\n}"

