const rtdal005059Source0001 = `test_that("throw() is standalone", {
  stenv <- environment(throw)
  objs <- ls(stenv, all.names = TRUE)
  funs <- Filter(function(x) is.function(stenv[[x]]), objs)
  funobjs <- mget(funs, stenv)
  for (f in funobjs) {
    expect_identical(environmentName(topenv(f)), "base")
  }

  skip_if_not_installed("codetools")
  expect_message(
    withCallingHandlers(
      res <- mapply(
        codetools::checkUsage,
        funobjs,
        funs,
        MoreArgs = list(report = message)
      ),
      message = function(c) {
        if (grepl(".hide_from_trace", c$message)) {
          invokeRestart("muffleMessage")
        }
      }
    ),
    NA
  )
})`

const rtdal005059Source0002 = `test_that("new_cond", {
  c <- new_cond("foo", "bar")
  expect_identical(class(c), "condition")
  expect_identical(c$message, "foobar")
})`

const rtdal005059Source0003 = `test_that("new_error", {
  c <- new_error("foo", "bar")
  expect_identical(
    class(c),
    c("rlib_error_3_0", "rlib_error", "error", "condition")
  )
  expect_identical(c$message, "foobar")
})`

const rtdal005059Source0004 = `test_that("throw() works with condition objects or strings", {
  expect_error(
    throw("foobar"),
    "foobar",
    class = "rlib_error"
  )
  expect_error(
    throw(new_error("foobar")),
    "foobar",
    class = "rlib_error"
  )
})`

const rtdal005059Source0005 = `test_that("parent must be an error object", {
  expect_error(
    throw(new_error("foobar"), parent = "nope"),
    "Parent condition must be a condition object",
    class = "rlib_error"
  )
})`

const rtdal005059Source0006 = `test_that("throw() adds the proper call, if requested", {
  f <- function() throw(new_error("ooops"))
  err <- tryCatch(f(), error = function(e) e)
  expect_s3_class(err, "rlib_error")
  expect_identical(deparse(err$call), "f()")

  g <- function() throw(new_error("ooops", call. = FALSE))
  err <- tryCatch(g(), error = function(e) e)
  expect_s3_class(err, "rlib_error")
  expect_null(err$call)
})`

const rtdal005059Source0007 = `test_that("throw() only stops for errors", {
  f <- function() throw(new_cond("nothing important"))

  expect_error(f(), NA)
})`

const rtdal005059Source0008 = `test_that("caught conditions have no trace", {
  f <- function() throw(new_error("nothing important"))

  cond <- tryCatch(f(), condition = function(e) e)
  expect_null(cond$trace)
})`

const rtdal005059Source0009 = "test_that(\"un-caught condition has trace\", {\n  skip_on_cran()\n\n  # We need to run this in a separate script, because\n  # testthat catches all conditions. We also cannot run it in callr::r()\n  # or similar, because those catch conditions as well.\n\n  sf <- tempfile(fileext = \".R\")\n  op <- sub(\"\\\\.R$\", \".rds\", sf)\n  so <- paste0(sf, \"out\")\n  se <- paste0(sf, \"err\")\n  on.exit(unlink(c(sf, op, so, se), recursive = TRUE), add = TRUE)\n\n  expr <- substitute(\n    {\n      f <- function() g()\n      g <- function() processx:::throw(processx:::new_error(\"oooops\"))\n      options(rlib_error_handler = function(c) {\n        saveRDS(c, file = `__op__`)\n      })\n      f()\n    },\n    list(\"__op__\" = op)\n  )\n\n  cat(deparse(expr), file = sf, sep = \"\\n\")\n\n  callr::rscript(sf, stdout = so, stderr = se)\n\n  cond <- readRDS(op)\n  expect_s3_class(cond, \"rlib_error\")\n  expect_s3_class(cond$trace, \"rlib_trace\")\n})"

const rtdal005059Source0010 = `test_that("chain_call", {
  do <- function() {
    chain_call(c_processx_base64_encode, "foobar")
  }
  cond <- tryCatch(
    do(),
    error = function(e) e
  )

  expect_equal(deparse(cond$call), "do()")
  expect_s3_class(cond, "c_error")
  expect_s3_class(cond, "rlib_error")
})`

const rtdal005059Source0011 = `test_that("errors from subprocess", {
  skip_if_not_installed("callr", minimum_version = "3.7.0.9000")
  err <- tryCatch(
    callr::r(function() 1 + "a"),
    error = function(e) e
  )
  expect_s3_class(err, "rlib_error")
  expect_s3_class(err$parent, "error")
  expect_false(is.null(err$parent_trace))
})`

const rtdal005059Source0012 = "test_that(\"error trace from subprocess\", {\n  skip_on_cran()\n  skip_if_not_installed(\"callr\", minimum_version = \"3.7.0.9000\")\n\n  sf <- tempfile(fileext = \".R\")\n  op <- sub(\"\\\\.R$\", \".rds\", sf)\n  so <- paste0(sf, \"out\")\n  se <- paste0(sf, \"err\")\n  on.exit(unlink(c(sf, op, so, se), recursive = TRUE), add = TRUE)\n\n  expr <- substitute(\n    {\n      h <- function() callr::r(function() 1 + \"a\")\n      options(rlib_error_handler = function(c) {\n        saveRDS(c, file = `__op__`)\n        # quit after the first, because the other one is caught here as well\n        q()\n      })\n      h()\n    },\n    list(\"__op__\" = op)\n  )\n\n  cat(deparse(expr), file = sf, sep = \"\\n\")\n\n  callr::rscript(sf, stdout = so, stderr = se)\n\n  cond <- readRDS(op)\n\n  expect_s3_class(cond, \"rlib_error\")\n  expect_s3_class(cond$parent, \"error\")\n  expect_s3_class(cond$trace, \"rlib_trace\")\n})"

const rtdal005059Source0013 = "test_that(\"error trace from throw() in subprocess\", {\n  skip_on_cran()\n  skip_if_not_installed(\"callr\", minimum_version = \"3.7.0.9000\")\n\n  sf <- tempfile(fileext = \".R\")\n  op <- sub(\"\\\\.R$\", \".rds\", sf)\n  so <- paste0(sf, \"out\")\n  se <- paste0(sf, \"err\")\n  on.exit(unlink(c(sf, op, so, se), recursive = TRUE), add = TRUE)\n\n  expr <- substitute(\n    {\n      h <- function() callr::r(function() processx::run(\"does-not-exist---\"))\n      options(rlib_error_handler = function(c) {\n        saveRDS(c, file = `__op__`)\n        # quit after the first, because the other one is caught here as well\n        q()\n      })\n      h()\n    },\n    list(\"__op__\" = op)\n  )\n\n  cat(deparse(expr), file = sf, sep = \"\\n\")\n\n  callr::rscript(sf, stdout = so, stderr = se)\n\n  cond <- readRDS(op)\n\n  expect_s3_class(cond, \"rlib_error\")\n  expect_s3_class(cond$parent, \"rlib_error\")\n  expect_s3_class(cond$trace, \"rlib_trace\")\n})"

const rtdal005059Source0014 = `test_that("trace is not overwritten", {
  skip_on_cran()
  withr::local_options(list(rlib_error_always_trace = TRUE))
  err <- new_error("foobar")
  err$trace <- "not really"

  err2 <- tryCatch(throw(err), error = function(e) e)
  expect_identical(err2$trace, "not really")
})`

const rtdal005059Source0015 = `test_that("error is printed on error", {
  skip_on_cran()

  sf <- tempfile(fileext = ".R")
  op <- sub("\\.R$", ".rds", sf)
  so <- paste0(sf, "out")
  se <- paste0(sf, "err")
  on.exit(unlink(c(sf, op, so, se), recursive = TRUE), add = TRUE)

  expr <- substitute({
    options(rlib_interactive = TRUE)
    processx::run(basename(tempfile()))
  })

  cat(deparse(expr), file = sf, sep = "\n")

  callr::rscript(
    sf,
    stdout = so,
    stderr = se,
    fail_on_status = FALSE,
    show = FALSE
  )

  selines <- readLines(so)
  expect_true(
    any(grepl("No such file or directory", selines)) ||
      any(grepl("Command .* not found", selines))
  )
  expect_false(any(grepl("Stack trace", selines)))
})`

const rtdal005059Source0016 = `test_that("trace is printed on error in non-interactive sessions", {
  sf <- tempfile(fileext = ".R")
  so <- paste0(sf, "out")
  se <- paste0(sf, "err")
  on.exit(unlink(c(sf, so, se), recursive = TRUE), add = TRUE)

  expr <- substitute({
    processx::run(basename(tempfile()))
  })

  cat(deparse(expr), file = sf, sep = "\n")

  callr::rscript(
    sf,
    stdout = so,
    stderr = se,
    fail_on_status = FALSE,
    show = FALSE
  )

  selines <- readLines(se)
  expect_true(
    any(grepl("No such file or directory", selines)) ||
      any(grepl("Command .* not found", selines))
  )
  expect_true(any(grepl("Backtrace", selines)))
})`

const rtdal005059Source0017 = "test_that(\"can pass frame as error call in `new_error()`\", {\n  check_bar <- function(call = parent.frame()) {\n    check_foo(call = call)\n  }\n  check_foo <- function(call = parent.frame()) {\n    throw(new_error(\"my message\", call. = call))\n  }\n  f <- function() check_bar()\n  g <- function() check_foo()\n\n  expect_snapshot(error = TRUE, {\n    f()\n    g()\n  })\n})"

const rtdal005059Source0018 = "test_that(\"can pass frame as error call in `throw()`\", {\n  check_bar <- function(call = parent.frame()) {\n    check_foo(call = call)\n  }\n  check_foo <- function(call = parent.frame()) {\n    throw(new_error(\"my message\"), call = call)\n  }\n  f <- function() check_bar()\n  g <- function() check_foo()\n\n  expect_snapshot(error = TRUE, {\n    f()\n    g()\n  })\n})"

