const rtdal005080Source0005 = "promiseDomain <- list(\n  onThen = function(onFulfilled, onRejected, onFinally) {\n    force(onFulfilled)\n    force(onRejected)\n    force(onFinally)\n\n    # Verify that if onFinally is non-NULL, onFulfilled and onRejected are NULL\n    if (\n      !is.null(onFinally) && (!is.null(onFulfilled) || !is.null(onRejected))\n    ) {\n      stop(\n        \"A single `then` call cannot combine `onFinally` with `onFulfilled`/`onRejected`\"\n      )\n    }\n\n    domain <- current_promise_domain()\n\n    shouldWrapFinally <- !is.null(onFinally) &&\n      !is.null(domain) &&\n      !is.null(domain$wrapOnFinally)\n\n    newOnFinally <- if (shouldWrapFinally) {\n      domain$wrapOnFinally(onFinally)\n    } else {\n      onFinally\n    }\n\n    if (!is.null(newOnFinally)) {\n      spliced <- spliceOnFinally(newOnFinally)\n      onFulfilled <- spliced$onFulfilled\n      onRejected <- spliced$onRejected\n    }\n\n    shouldWrapFulfilled <- !is.null(onFulfilled) &&\n      !is.null(domain) &&\n      !shouldWrapFinally\n    shouldWrapRejected <- !is.null(onRejected) &&\n      !is.null(domain) &&\n      !shouldWrapFinally\n\n    results <- list(\n      onFulfilled = if (shouldWrapFulfilled) {\n        domain$wrapOnFulfilled(onFulfilled)\n      } else {\n        onFulfilled\n      },\n      onRejected = if (shouldWrapRejected) {\n        domain$wrapOnRejected(onRejected)\n      } else {\n        onRejected\n      }\n    )\n    results <- results[!vapply(results, is.null, logical(1))]\n    # If there's a domain, ensure that before any callback is invoked, we\n    # reenter the domain. This is important for this kind of code:\n    #\n    #     with_promise_domain(domain, {\n    #       async_sleep(0.1) |>\n    #         then(\\(x) {async_sleep(0.1)}) |>\n    #         then(\\(x) {\n    #           # Without re-entry, this would be outside the domain!\n    #         })\n    #     })\n    #\n    # It's important to reenter even if domain is NULL. In that case, we need to\n    # ensure that the current domain is set to NULL while the callback executes.\n    results <- lapply(results, wrap_callback_reenter, domain = domain)\n    results\n  },\n  onError = function(error) {\n    domain <- current_promise_domain()\n    if (is.null(domain)) {\n      return()\n    }\n    domain$onError(error)\n  }\n)"

const rtdal005080Source0006 = "wrap_callback_reenter <- function(callback, domain) {\n  force(callback)\n  force(domain)\n\n  wrapper <- function(...) {\n    # replace = TRUE because we don't care what the current domain is; we're\n    # (temporarily) putting the world back to the way it was when the callback\n    # was bound to a promise.\n    reenter_promise_domain(domain, callback(...), replace = TRUE)\n  }\n\n  # There are parts of this package that will inspect formals() to see if\n  # there's a `.visible` parameter in the callback. So it's important to have\n  # the returned wrapper have the same formals as the original callback.\n  wrap_with_signature(wrapper, formals(callback))\n}"

const rtdal005080Source0007 = "wrap_with_signature <- function(func, formal_args) {\n  # func must have a `...` signature\n  stopifnot(\"...\" %in% names(formals(func)))\n\n  args <- names(formal_args)\n  recall <- rlang::call2(\n    func,\n    !!!rlang::set_names(lapply(args, as.symbol), args)\n  )\n\n  rlang::new_function(formal_args, recall)\n}"

const rtdal005080Source0010 = `with_promise_domain <- function(domain, expr, replace = FALSE) {
  oldval <- current_promise_domain()
  if (replace) {
    globals$domain <- domain
  } else {
    globals$domain <- compose_domains(oldval, domain)
  }
  on.exit(globals$domain <- oldval)

  if (!is.null(domain)) domain$wrapSync(expr) else force(expr)
}`

const rtdal005080Source0011 = `reenter_promise_domain <- function(domain, expr, replace) {
  oldval <- current_promise_domain()
  if (replace) {
    globals$domain <- domain
  } else {
    globals$domain <- compose_domains(oldval, domain)
  }
  on.exit(globals$domain <- oldval)

  force(expr)
}`

const rtdal005080Source0012 = `new_promise_domain <- function(
  wrapOnFulfilled = identity,
  wrapOnRejected = identity,
  wrapSync = force,
  onError = force,
  ...,
  wrapOnFinally = NULL
) {
  list2env(
    list(
      wrapOnFulfilled = wrapOnFulfilled,
      wrapOnRejected = wrapOnRejected,
      wrapOnFinally = wrapOnFinally,
      wrapSync = wrapSync,
      onError = onError,
      ...
    ),
    parent = emptyenv()
  )
}`

const rtdal005080Source0013 = "compose_domains <- function(base, new) {\n  if (is.null(base)) {\n    return(new)\n  }\n\n  list(\n    # The `...` of `new_promise_domain` are not automatically composed here.\n    # For now, pass through the otel span promise domain flag\n    .otel_promise_domain = has_otel_promise_domain(base) ||\n      has_otel_promise_domain(new),\n    wrapOnFulfilled = function(onFulfilled) {\n      # Wrap new domain first (innermost), then base domain (outermost)\n      # This ensures that the new domain wraps most closely to the callback\n      new_wrapped <- new$wrapOnFulfilled(onFulfilled)\n      base$wrapOnFulfilled(new_wrapped)\n    },\n    wrapOnRejected = function(onRejected) {\n      # Wrap new domain first (innermost), then base domain (outermost)\n      # This ensures that the new domain wraps most closely to the callback\n      new_wrapped <- new$wrapOnRejected(onRejected)\n      base$wrapOnRejected(new_wrapped)\n    },\n    # Only include the new wrapSync, assuming that we've already applied the\n    # base domain's wrapSync. This assumption won't hold if we either export\n    # compose_domains in the future, or if we use it in cases where the base\n    # domain isn't currently active.\n    wrapSync = new$wrapSync,\n    onError = function(e) {\n      base$onError(e)\n      new$onError(e)\n    }\n  )\n}"

