const rtdal005089Source0001 = `Promise <- function() {
  self <- new.env(parent = emptyenv())
  private <- new.env(parent = emptyenv())

  private$state <- "pending"
  private$value <- NULL
  private$visible <- TRUE
  private$publicResolveRejectCalled <- FALSE
  private$onFulfilled <- list()
  private$onRejected <- list()
  private$onFinally <- list()
  private$rejectionHandled <- FALSE

  private$doResolve <- function(value) {
    val <- withVisible(value)
    value <- val$value
    visible <- val$visible

    if (is.promising(value)) {
      value <- as.promise(value)
      if (identical(self, attr(value, "promise_impl", exact = TRUE))) {
        return(private$doReject(simpleError(
          "Chaining cycle detected for promise"
        )))
      }
      # This then() call doesn't need promise domains; semantically, it doesn't
      # really exist, as it's just a convenient way to implement the new promise
      # inhabiting the old promise's corpse.
      without_promise_domain({
        value$then(
          private$doResolve,
          private$doReject
        )
      })
    } else {
      private$doResolveFinalValue(value, visible)
    }
  }

  private$doReject <- function(reason) {
    if (is.promising(reason)) {
      reason <- as.promise(reason)
      # This then() call doesn't need promise domains; semantically, it doesn't
      # really exist, as it's just a convenient way to implement the new promise
      # inhabiting the old promise's corpse.
      without_promise_domain({
        reason$then(
          private$doResolve,
          private$doReject
        )
      })
    } else {
      private$doRejectFinalReason(reason)
    }
  }

  # These "final" versions of resolve/reject are for when we've
  # established that the value/reason is not itself a promise.
  private$doResolveFinalValue <- function(value, visible) {
    private$value <- value
    private$visible <- visible
    private$state <- "fulfilled"

    later(function() {
      lapply(private$onFulfilled, function(f) {
        f(private$value, private$visible)
      })
      private$onFulfilled <- list()
    })
  }

  private$doRejectFinalReason <- function(reason) {
    private$value <- reason
    private$state <- "rejected"

    later(function() {
      lapply(private$onRejected, function(f) {
        private$rejectionHandled <- TRUE
        f(private$value)
      })
      private$onRejected <- list()

      later(
        function() {
          if (!private$rejectionHandled) {
            # warning() was unreliable here
            cat(
              file = stderr(),
              "Unhandled promise error: ",
              reason$message,
              "\n",
              sep = ""
            )
          }
        }
      )
    })
  }

  self$status <- function() {
    private$state
  }

  self$resolve <- function(value) {
    # Only allow this to be called once, then no-op.
    if (private$publicResolveRejectCalled) {
      return(invisible())
    }
    private$publicResolveRejectCalled <- TRUE

    tryCatch(
      {
        # Important: Do not trigger evaluation of value before
        # passing to doResolve. doResolve calls withVisible() on
        # value, so evaluating it before that point will cause
        # the visibility to be lost.
        private$doResolve(value)
      },
      error = function(err) {
        private$doReject(err)
      }
    )

    invisible()
  }

  self$reject <- function(reason) {
    # Only allow this to be called once, then no-op.
    if (private$publicResolveRejectCalled) {
      return(invisible())
    }
    private$publicResolveRejectCalled <- TRUE

    tryCatch(
      {
        force(reason)
        if (is.character(reason)) {
          reason <- simpleError(reason)
        }
        private$doReject(reason)
      },
      error = function(err) {
        private$doReject(err)
      }
    )

    invisible()
  }

  self$then <- function(
    onFulfilled = NULL,
    onRejected = NULL,
    onFinally = NULL
  ) {
    onFulfilled <- normalizeOnFulfilled(onFulfilled)
    onRejected <- normalizeOnRejected(onRejected)
    if (!is.function(onFinally)) {
      onFinally <- NULL
    }

    promise2 <- promise(function(resolve, reject) {
      res <- promiseDomain$onThen(onFulfilled, onRejected, onFinally)

      if (!is.null(res)) {
        onFulfilled <- res$onFulfilled
        onRejected <- res$onRejected
      }

      handleFulfill <- function(value, visible) {
        if (is.function(onFulfilled)) {
          resolve(onFulfilled(value, visible))
        } else {
          resolve(if (visible) value else invisible(value))
        }
      }

      handleReject <- function(reason) {
        if (is.function(onRejected)) {
          # Yes, resolve, not reject.
          resolve(onRejected(reason))
        } else {
          # Yes, reject, not resolve.
          reject(reason)
        }
      }

      if (private$state == "pending") {
        private$onFulfilled <- c(
          private$onFulfilled,
          list(
            handleFulfill
          )
        )
        private$onRejected <- c(
          private$onRejected,
          list(
            handleReject
          )
        )
      } else if (private$state == "fulfilled") {
        later(function() {
          handleFulfill(private$value, private$visible)
        })
      } else if (private$state == "rejected") {
        later(function() {
          private$rejectionHandled <- TRUE
          handleReject(private$value)
        })
      } else {
        stop("Unexpected state ", private$state)
      }
    })

    invisible(promise2)
  }

  self$catch <- function(onRejected) {
    invisible(self$then(onRejected = onRejected))
  }

  self$finally <- function(onFinally) {
    invisible(self$then(
      onFinally = onFinally
    ))
  }

  self$format <- function() {
    if (private$state == "pending") {
      "<Promise [pending]>"
    } else {
      classname <- class(private$value)[[1]]
      if (length(classname) == 0) {
        classname <- ""
      }

      sprintf("<Promise [%s: %s]>", private$state, classname)
    }
  }

  self$.__enclos_env__ <- list(private = private)
  class(self) <- "Promise"
  self
}`

const rtdal005089Source0002 = "normalizeOnFulfilled <- function(onFulfilled) {\n  if (!is.function(onFulfilled)) {\n    if (!is.null(onFulfilled)) {\n      warning(\"`onFulfilled` must be a function or `NULL`\")\n    }\n    return(NULL)\n  }\n\n  args <- formals(onFulfilled)\n  arg_count <- length(args)\n\n  if (arg_count >= 2 && names(args)[[2]] == \".visible\") {\n    onFulfilled\n  } else if (arg_count > 0) {\n    function(value, .visible) {\n      if (isTRUE(.visible)) {\n        onFulfilled(value)\n      } else {\n        onFulfilled(invisible(value))\n      }\n    }\n  } else {\n    function(value, .visible) {\n      onFulfilled()\n    }\n  }\n}"

const rtdal005089Source0003 = "normalizeOnRejected <- function(onRejected) {\n  if (!is.function(onRejected)) {\n    if (!is.null(onRejected)) {\n      warning(\"`onRejected` must be a function or `NULL`\")\n    }\n    return(NULL)\n  }\n\n  args <- formals(onRejected)\n  arg_count <- length(args)\n\n  if (arg_count >= 1) {\n    onRejected\n  } else if (arg_count == 0) {\n    function(reason) {\n      onRejected()\n    }\n  }\n}"

const rtdal005089Source0004 = `promise <- function(action) {
  if (is.function(action)) {
    if (length(formals(action)) != 2) {
      stop("'action' function must have two arguments")
    }
  } else if (inherits(action, "formula")) {
    if (length(action) != 2) {
      stop("'action' must be a function or one-sided formula")
    }
  } else {
    stop("Invalid action argument--should be a function")
  }

  p <- Promise()

  tryCatch(
    {
      if (is.function(action)) {
        action(p$resolve, p$reject)
      } else if (inherits(action, "formula")) {
        eval(
          action[[2]],
          list(
            resolve = p$resolve,
            reject = p$reject,
            return = function(value) {
              warning("Can't return a value from a promise, use resolve/reject")
            }
          ),
          environment(action)
        )
      }
    },
    error = function(e) {
      if (p$status() == "pending") {
        p$reject(e)
      } else {
        # Too late to do anything useful. Just notify.
        warning(e)
      }
    }
  )
  structure(
    list(
      then = p$then,
      catch = p$catch,
      finally = p$finally
    ),
    class = "promise",
    promise_impl = p
  )
}`

const rtdal005089Source0014 = "as.promise.Future <- function(x) {\n  # We want to create a promise only once for each Future object, and cache it\n  # as an attribute. This spares us from having multiple polling loops waiting\n  # for the same Future.\n  #\n  ## Note: 2025-07-barret:\n  ## Active bindings will not work as `{future}` does not proactively retrieve results. A poll must be used.\n  #\n  ## Note: 2025-08-barret:\n  ## From conversation with Henrik, while it may be possible to use `immediateCondition` within future to _immediately_ send a value back from a worker to the main R session,\n  ## `future::resolved()` is still required to pull the _immediate_ value into the R session (even when the future has not fully resolved yet).\n  ## Therefore, the polling mechanism below is still required.\n  ## For comparison, mirai has a background process that waits for results and will interrupt the main R session with the value.\n\n  cached <- attr(x, \"converted_promise\", exact = TRUE)\n  if (!is.null(cached)) {\n    return(cached)\n  }\n\n  p <- promise(function(resolve, reject) {\n    poll_interval <- 0.1\n    check <- function() {\n      # timeout = 0 is important, the default waits for 200ms\n      is_resolved <- tryCatch(\n        {\n          future::resolved(x, timeout = 0)\n        },\n        FutureError = function(e) {\n          reject(e)\n          TRUE\n        }\n      )\n      if (is_resolved) {\n        tryCatch(\n          {\n            result <- future::value(x, signal = TRUE)\n            resolve(result)\n          },\n          FutureError = function(e) {\n            reject(e)\n            TRUE\n          },\n          error = function(e) {\n            reject(e)\n          }\n        )\n      } else {\n        later(check, poll_interval)\n      }\n    }\n    check()\n  })\n\n  # Store the new promise for next time\n  attr(x, \"converted_promise\") <- p\n  p\n}"

