const rtdal005117Source0016 = `pr_Minkowski_prefun <- function(x, y, pairwise, p, reg_entry) {
    if (length(p$p) < 1)
        stop("Argument 'p' mandatory!")
    p <- p$p[[1L]]
    if (p <= 0)
        stop("'p' must not be smaller than 0.")
    if (!is.matrix(x)) {
        reg_entry$C_FUN <- FALSE
        reg_entry$loop <- TRUE
        reg_entry$FUN <- "pr_Minkowski"
    }
    list(x = if (!is.list(x)) 0 + x else x,
         y = if (!is.null(y)) if (!is.list(y)) 0 + y else y,
         pairwise = pairwise,
         p = p, reg_entry = reg_entry)
}`

